-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/chessplay/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, BOX_W, ROW_H, GAP = 20, kit.W - 40, 56, 10
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['engine'] = function()
-- The reader's chess player: alpha-beta search with iterative deepening, a quiescence search over
-- captures and promotions, the best move of the last depth tried first, captures by most valuable
-- victim / least valuable attacker, two killer moves a ply. The evaluation is material and
-- piece-square tables (pos.score, kept up to date by make), the king going to the middle in the
-- endgame, and a little noise per level so games differ.
--
-- think(pos, level, opts) is meant to run in a coroutine: every 200 nodes it asks opts.clock() and
-- calls coroutine.yield() once the slice (opts.slice_ms) is used up, so the host's callback limits
-- are kept and the screen stays responsive; past opts.limit_ms it stops and plays the best move of
-- the last depth it finished. Outside a coroutine (tests) it never yields.

local R = require('rules')
local E = {}

local MATE = 100000
local INF = 1000000

-- the levels: how deep, how long, how much noise (centipawns) at the root
E.LEVELS = {
  { name = 'Beginner', depth = 1, ms = 500, noise = 220, quiesce = false },
  { name = 'Easy', depth = 2, ms = 1500, noise = 80, quiesce = true },
  { name = 'Medium', depth = 4, ms = 3500, noise = 20, quiesce = true },
  { name = 'Hard', depth = 6, ms = 8000, noise = 6, quiesce = true },
}

local VALUE = R.VALUE
local KING_END = R.KING_END
local pst_index = R.pst_index
local gen, make, unmake, attacked, needs_check = R.gen, R.make, R.unmake, R.attacked, R.needs_check

-- the score for the side to move
local function evaluate(pos)
  local s = pos.score
  if pos.npm <= 1300 then
    -- the endgame: the kings come out (the middle-game table keeps them home)
    local wk, bk = pos.king[1], pos.king[-1]
    s = s + KING_END[pst_index(wk, 1)] - KING_END[pst_index(bk, -1)]
  end
  return s * pos.side
end
E.evaluate = evaluate

local Search = {}
Search.__index = Search

local function new_search(opts)
  local o = setmetatable({}, Search)
  o.clock = opts.clock or function() return 0 end
  o.slice = opts.slice_ms or 200
  o.limit = opts.limit_ms
  o.yield = opts.yield ~= false and coroutine.isyieldable()
  o.nodes = 0
  o.killers = {}
  o.start = o.clock()
  o.slice_start = o.start
  o.stopped = false
  o.use_q = opts.quiesce ~= false
  -- a move list and its order keys per ply, kept between nodes: no tables made while searching
  o.lists, o.keys = {}, {}
  return o
end

function Search:tick()
  self.nodes = self.nodes + 1
  if self.nodes % 200 ~= 0 then return end
  local now = self.clock()
  if self.limit and now - self.start >= self.limit then self.stopped = true; return end
  if self.yield and now - self.slice_start >= self.slice then
    coroutine.yield()
    self.slice_start = self.clock()
  end
end

function Search:buffers(ply)
  local l = self.lists[ply]
  if not l then l = {}; self.lists[ply] = l; self.keys[ply] = {} end
  return l, self.keys[ply]
end

-- order keys: the move to try first, captures (most valuable victim, least valuable attacker),
-- promotions, killers, the rest
local function score_moves(pos, list, keys, n, first, killers)
  local b = pos.b
  local k1, k2 = killers and killers[1], killers and killers[2]
  for i = 1, n do
    local m = list[i]
    local k
    if m == first then k = 1000000
    else
      local victim = b[(m // 128) % 128]
      if victim ~= 0 then
        if victim < 0 then victim = -victim end
        local att = b[m % 128]
        if att < 0 then att = -att end
        k = 100000 + victim * 100 - att
      elseif (m // 16384) % 8 ~= 0 then k = 90000 + (m // 16384) % 8
      elseif m == k1 or m == k2 then k = 80000
      else k = 0 end
    end
    keys[i] = k
  end
end

-- the next move in order: the best of i..n brought to i (a cut-off often comes after a few)
local function pick(list, keys, i, n)
  local bi, bk = i, keys[i]
  for j = i + 1, n do
    if keys[j] > bk then bi, bk = j, keys[j] end
  end
  if bi ~= i then
    list[i], list[bi] = list[bi], list[i]
    keys[i], keys[bi] = keys[bi], keys[i]
  end
  return list[i]
end

-- the whole list in order (the root, sorted once per depth)
local function order(pos, list, n, first, killers)
  local keys = {}
  score_moves(pos, list, keys, n, first, killers)
  for i = 1, n - 1 do pick(list, keys, i, n) end
end

function Search:quiesce(pos, alpha, beta, ply)
  self:tick()
  if self.stopped then return 0 end
  local stand = evaluate(pos)
  if stand >= beta then return stand end
  if stand > alpha then alpha = stand end
  if ply > 40 then return stand end
  local list, keys = self:buffers(ply)
  local n = gen(pos, list, 0, true)
  score_moves(pos, list, keys, n, nil, nil)
  local side, b = pos.side, pos.b
  local king = pos.king[side]
  local chk = n > 0 and attacked(pos, king, -side)
  for i = 1, n do
    local m = pick(list, keys, i, n)
    -- a capture that cannot bring the score up to alpha even when it wins the piece: skip it
    local victim = b[(m // 128) % 128]
    if victim < 0 then victim = -victim end
    local gain = victim ~= 0 and VALUE[victim] or 100
    if (m // 16384) % 8 == 0 and stand + gain + 200 < alpha then goto continue end
    do
      local u = make(pos, m)
      if not needs_check(m, king, chk) or not attacked(pos, pos.king[side], -side) then
        local v = -self:quiesce(pos, -beta, -alpha, ply + 1)
        unmake(pos, m, u)
        if self.stopped then return 0 end
        if v >= beta then return v end
        if v > alpha then alpha = v end
      else
        unmake(pos, m, u)
      end
    end
    ::continue::
  end
  return alpha
end

function Search:alphabeta(pos, depth, alpha, beta, ply, null_ok)
  self:tick()
  if self.stopped then return 0 end
  local side = pos.side
  local check = attacked(pos, pos.king[side], -side)
  if check and ply < 24 then depth = depth + 1 end    -- look one ply further out of a check
  if depth <= 0 then
    if self.use_q then return self:quiesce(pos, alpha, beta, ply) end
    return evaluate(pos)
  end
  if pos.half >= 100 then return 0 end
  -- the null move: even after passing, the side to move stays above beta, so this position will
  -- not be allowed; not in check, nor in the endgame, where passing can be the better move
  if null_ok and not check and depth >= 3 and pos.npm > 1300 and evaluate(pos) >= beta then
    local ep = pos.ep
    pos.ep, pos.side = 0, -side
    local v = -self:alphabeta(pos, depth - 3, -beta, -beta + 1, ply + 1, false)
    pos.ep, pos.side = ep, side
    if self.stopped then return 0 end
    if v >= beta then return beta end
  end
  local list, keys = self:buffers(ply)
  local n = gen(pos, list, 0, false)
  local killers = self.killers[ply]
  score_moves(pos, list, keys, n, nil, killers)
  local legal, best = 0, -INF
  local king = pos.king[side]
  for i = 1, n do
    local m = pick(list, keys, i, n)
    local u = make(pos, m)
    if not needs_check(m, king, check) or not attacked(pos, pos.king[side], -side) then
      legal = legal + 1
      local v = -self:alphabeta(pos, depth - 1, -beta, -alpha, ply + 1, true)
      unmake(pos, m, u)
      if self.stopped then return 0 end
      if v > best then best = v end
      if v > alpha then alpha = v end
      if alpha >= beta then
        if pos.b[(m // 128) % 128] == 0 then          -- a quiet move that cut: remember it
          killers = killers or {}
          if killers[1] ~= m then killers[2] = killers[1]; killers[1] = m end
          self.killers[ply] = killers
        end
        break
      end
    else
      unmake(pos, m, u)
    end
  end
  if legal == 0 then return check and -(MATE - ply) or 0 end
  return best
end

-- the best move for the side to move, with its score, the depth reached and the nodes searched.
-- opts: clock, slice_ms, limit_ms (else the level's), random (a function returning 0..1)
function E.think(pos, level, opts)
  opts = opts or {}
  local L = E.LEVELS[level] or E.LEVELS[3]
  local s = new_search({ clock = opts.clock, slice_ms = opts.slice_ms, limit_ms = opts.limit_ms or L.ms,
                         yield = opts.yield, quiesce = L.quiesce })
  local random = opts.random or math.random
  local root = R.legal(pos)
  if #root == 0 then return nil end
  -- a little noise per root move, fixed for the whole search, so the reader does not always play the same
  local noise = {}
  for _, m in ipairs(root) do noise[m] = math.floor((random() - 0.5) * 2 * L.noise) end
  local best, best_score, reached = root[1], -INF, 0
  for depth = 1, L.depth do
    local alpha, beta = -INF, INF
    local this_best, this_score = nil, -INF
    order(pos, root, #root, best, nil)
    for _, m in ipairs(root) do
      local u = make(pos, m)
      local v = -s:alphabeta(pos, depth - 1, -beta, -alpha + L.noise, 1, true)
      unmake(pos, m, u)
      if s.stopped then break end
      local score = v + (math.abs(v) < MATE - 1000 and noise[m] or 0)
      if score > this_score then this_best, this_score = m, score end
      if score > alpha then alpha = score end
    end
    if s.stopped then
      -- a part of this depth: its best is still good when it beat the last depth's choice
      if this_best and this_score > best_score then best, best_score = this_best, this_score end
      break
    end
    best, best_score, reached = this_best, this_score, depth
    if math.abs(this_score) >= MATE - 1000 then break end    -- a forced mate found: no need to look further
  end
  return best, best_score, reached, s.nodes
end

E.MATE = MATE
return E
end

__mods['pieces'] = function()
-- The pieces, drawn as boxes (the fonts may lack chess symbols): the same pictures as Chess puzzles
-- (apps/chess/src/main.lua). RUNS[p] for 'k', 'q', ... is the solid black piece, RUNS['K'] ... the
-- outline of the white one; each is a list of { row, from, to, rows } on a 20 x 20 grid.

local PIECES = {
  k = { '.........##.........', '........####........', '.........##.........', '........####........', '.......######.......', '..####..####..####..', '.######.####.######.', '##################..', '####################', '####################', '.##################.', '..################..', '...##############...', '....############....', '....############....', '...##############...', '..################..', '..################..', '....................', '....................' },
  q = { '....................', '..##.....##.....##..', '..##....####....##..', '...#.....##.....#...', '...##....##....##...', '...###..####..###...', '...####.####.####...', '....############....', '....############....', '.....##########.....', '.....##########.....', '......########......', '.....##########.....', '....############....', '...##############...', '...##############...', '..################..', '..################..', '....................', '....................' },
  r = { '....................', '....................', '...###..####..###...', '...###..####..###...', '...##############...', '...##############...', '....############....', '.....##########.....', '.....##########.....', '.....##########.....', '.....##########.....', '.....##########.....', '.....##########.....', '....############....', '...##############...', '..################..', '..################..', '..################..', '....................', '....................' },
  b = { '....................', '.........##.........', '........####........', '........####........', '.......######.......', '......###.####......', '......##.#####......', '.....###.######.....', '.....##########.....', '.....##########.....', '......########......', '.......######.......', '......########......', '.......######.......', '......########......', '.....##########.....', '...##############...', '...##############...', '....................', '....................' },
  n = { '....................', '........##.##.......', '.......#######......', '......#########.....', '.....###.#######....', '....############....', '...##############...', '..######.#########..', '..#####...########..', '...###....########..', '..........#######...', '.........########...', '........########....', '.......#########....', '......##########....', '.....###########....', '....############....', '...##############...', '...##############...', '....................' },
  p = { '....................', '....................', '........####........', '.......######.......', '.......######.......', '.......######.......', '........####........', '......########......', '.......######.......', '........####........', '........####........', '.......######.......', '......########......', '.....##########.....', '....############....', '....############....', '...##############...', '...##############...', '....................', '....................' },
}

-- each piece as filled boxes { row, from, to, rows }: the runs of '#' in each row, a run that
-- repeats on the next rows becoming one taller box. Few boxes matter: the host draws about 1024
-- commands a screen and leaves out the rest.
local RUNS = {}
local function runs_of(rows)
  local out, open = {}, {}
  for r, row in ipairs(rows) do
    local here = {}
    local c = 1
    while c <= #row do
      if row:sub(c, c) == '#' then
        local e = c
        while e < #row and row:sub(e + 1, e + 1) == '#' do e = e + 1 end
        local key = c .. ':' .. e
        local box = open[key]
        if box and box[1] + box[4] == r then box[4] = box[4] + 1
        else box = { r, c, e, 1 }; out[#out + 1] = box end
        here[key] = box
        c = e + 1
      else
        c = c + 1
      end
    end
    open = here
  end
  return out
end
local function outline(rows)
  local h, w = #rows, #rows[1]
  local function on(r, c) return r >= 1 and r <= h and c >= 1 and c <= w and rows[r]:sub(c, c) == '#' end
  local out = {}
  for r = 1, h do
    local t = {}
    for c = 1, w do
      local edge = on(r, c) and not (on(r + 1, c) and on(r - 1, c) and on(r, c + 1) and on(r, c - 1))
      t[c] = edge and '#' or '.'
    end
    out[r] = table.concat(t)
  end
  return out
end
for k, rows in pairs(PIECES) do
  RUNS[k] = runs_of(rows)
  RUNS[k:upper()] = runs_of(outline(rows))
end
return RUNS
end

__mods['rules'] = function()
-- The rules of chess, with no screen: positions, legal moves, check, mate, the draws, and moves
-- as UCI ("e2e4", "e7e8q") and SAN ("Nf3", "exd5", "O-O", "e8=Q+").
--
-- The board is a 10 x 12 mailbox (b[0..119]): a1 is 21, h1 28, a8 91, h8 98; the squares around
-- are OFF, so a knight or a slider stops there without bounds checks. Pieces are numbers: 1 pawn,
-- 2 knight, 3 bishop, 4 rook, 5 queen, 6 king, positive for White, negative for Black, 0 empty.
-- A move is one integer: from + to * 128 + promotion * 16384 + flag * 131072 (flag 1 en passant,
-- 2 castling, 4 a pawn's double step), so lists of moves are plain arrays of numbers.
--
-- make(pos, m) changes the position and unmake(pos, m) puts it back, the last move made first:
-- what unmake needs goes on a stack in the position (pos.st), so no table is made per move. Both
-- keep the squares of each side's pieces (pos.pl[side], counted in pos.pn[side], with pos.pi
-- giving each square's place in its list) so move generation visits only those, a material and
-- piece-square score (pos.score, White's view) and the material other than pawns (pos.npm).

local R = {}

local OFF = 7
R.OFF = OFF
local N_DIRS = { -21, -19, -12, -8, 8, 12, 19, 21 }
local B_DIRS = { -11, -9, 9, 11 }
local R_DIRS = { -10, -1, 1, 10 }
local K_DIRS = { -11, -10, -9, -1, 1, 9, 10, 11 }
R.VALUE = { 100, 320, 330, 500, 900, 0 }
local VALUE = R.VALUE
local CHARS = 'pnbrqk'

-- piece-square tables (the "simplified evaluation function"), a8 first as printed, White's view
local PST = {
  { 0, 0, 0, 0, 0, 0, 0, 0, 50, 50, 50, 50, 50, 50, 50, 50, 10, 10, 20, 30, 30, 20, 10, 10, 5, 5, 10, 25, 25, 10, 5, 5,
    0, 0, 0, 20, 20, 0, 0, 0, 5, -5, -10, 0, 0, -10, -5, 5, 5, 10, 10, -20, -20, 10, 10, 5, 0, 0, 0, 0, 0, 0, 0, 0 },
  { -50, -40, -30, -30, -30, -30, -40, -50, -40, -20, 0, 0, 0, 0, -20, -40, -30, 0, 10, 15, 15, 10, 0, -30,
    -30, 5, 15, 20, 20, 15, 5, -30, -30, 0, 15, 20, 20, 15, 0, -30, -30, 5, 10, 15, 15, 10, 5, -30,
    -40, -20, 0, 5, 5, 0, -20, -40, -50, -40, -30, -30, -30, -30, -40, -50 },
  { -20, -10, -10, -10, -10, -10, -10, -20, -10, 0, 0, 0, 0, 0, 0, -10, -10, 0, 5, 10, 10, 5, 0, -10,
    -10, 5, 5, 10, 10, 5, 5, -10, -10, 0, 10, 10, 10, 10, 0, -10, -10, 10, 10, 10, 10, 10, 10, -10,
    -10, 5, 0, 0, 0, 0, 5, -10, -20, -10, -10, -10, -10, -10, -10, -20 },
  { 0, 0, 0, 0, 0, 0, 0, 0, 5, 10, 10, 10, 10, 10, 10, 5, -5, 0, 0, 0, 0, 0, 0, -5, -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5, -5, 0, 0, 0, 0, 0, 0, -5, -5, 0, 0, 0, 0, 0, 0, -5, 0, 0, 0, 5, 5, 0, 0, 0 },
  { -20, -10, -10, -5, -5, -10, -10, -20, -10, 0, 0, 0, 0, 0, 0, -10, -10, 0, 5, 5, 5, 5, 0, -10, -5, 0, 5, 5, 5, 5, 0, -5,
    0, 0, 5, 5, 5, 5, 0, -5, -10, 5, 5, 5, 5, 5, 0, -10, -10, 0, 5, 0, 0, 0, 0, -10, -20, -10, -10, -5, -5, -10, -10, -20 },
  { -30, -40, -40, -50, -50, -40, -40, -30, -30, -40, -40, -50, -50, -40, -40, -30, -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30, -20, -30, -30, -40, -40, -30, -30, -20, -10, -20, -20, -20, -20, -20, -20, -10,
    20, 20, 0, 0, 0, 0, 20, 20, 20, 30, 10, 0, 0, 10, 30, 20 },
}
-- the king in the endgame: to the middle
R.KING_END = { -50, -40, -30, -20, -20, -30, -40, -50, -30, -20, -10, 0, 0, -10, -20, -30, -30, -10, 20, 30, 30, 20, -10, -30,
  -30, -10, 30, 40, 40, 30, -10, -30, -30, -10, 30, 40, 40, 30, -10, -30, -30, -10, 20, 30, 30, 20, -10, -30,
  -30, -30, 0, 0, 0, 0, -30, -30, -50, -30, -30, -30, -30, -30, -30, -50 }

-- the table index of a square for a side: 1..64, a8 first for White, mirrored for Black
local function pst_index(s, side)
  local f, r = (s - 21) % 10, (s - 21) // 10
  if side > 0 then return (7 - r) * 8 + f + 1 end
  return r * 8 + f + 1
end
R.pst_index = pst_index

-- the score a piece adds where it stands (White's view)
local function worth(p, s)
  if p > 0 then return VALUE[p] + PST[p][pst_index(s, 1)] end
  return -(VALUE[-p] + PST[-p][pst_index(s, -1)])
end

function R.square(name)                  -- 'e4' -> 55
  return 21 + (name:byte(2) - 49) * 10 + (name:byte(1) - 97)
end
function R.name(s)                       -- 55 -> 'e4'
  local f, r = (s - 21) % 10, (s - 21) // 10
  return string.char(97 + f, 49 + r)
end
function R.file(s) return (s - 21) % 10 end
function R.rank(s) return (s - 21) // 10 end

function R.move_from(m) return m % 128 end
function R.move_to(m) return (m // 128) % 128 end
function R.move_promo(m) return (m // 16384) % 8 end
function R.move_flag(m) return m // 131072 end
local function mv(from, to, promo, flag) return from + to * 128 + (promo or 0) * 16384 + (flag or 0) * 131072 end
R.mv = mv

------------------------------------------------------------------ positions

local START = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1'
R.START = START

local function rescore(pos)
  local score, npm = 0, 0
  local pl, pn, pi = { [1] = {}, [-1] = {} }, { [1] = 0, [-1] = 0 }, {}
  for s = 21, 98 do
    local p = pos.b[s]
    if p ~= 0 and p ~= OFF then
      score = score + worth(p, s)
      local a = p > 0 and p or -p
      local side = p > 0 and 1 or -1
      if a ~= 1 and a ~= 6 then npm = npm + VALUE[a] end
      if a == 6 then pos.king[side] = s end
      pn[side] = pn[side] + 1
      pl[side][pn[side]] = s
      pi[s] = pn[side]
    end
  end
  pos.score, pos.npm = score, npm
  pos.pl, pos.pn, pos.pi = pl, pn, pi
  pos.st, pos.sp = {}, 0
end

function R.from_fen(fen)
  local rows, side, castle, ep, half, full = fen:match('^(%S+)%s+(%a)%s+(%S+)%s+(%S+)%s*(%d*)%s*(%d*)')
  if not rows then return nil end
  local b = {}
  for s = 0, 119 do b[s] = OFF end
  local r, f = 7, 0
  for ch in rows:gmatch('.') do
    if ch == '/' then r, f = r - 1, 0
    elseif ch:match('%d') then
      for _ = 1, tonumber(ch) do b[21 + r * 10 + f] = 0; f = f + 1 end
    else
      local k = CHARS:find(ch:lower(), 1, true)
      if not k then return nil end
      b[21 + r * 10 + f] = ch:lower() == ch and -k or k
      f = f + 1
    end
  end
  local c = 0
  if castle:find('K', 1, true) then c = c | 1 end
  if castle:find('Q', 1, true) then c = c | 2 end
  if castle:find('k', 1, true) then c = c | 4 end
  if castle:find('q', 1, true) then c = c | 8 end
  local pos = { b = b, side = side == 'b' and -1 or 1, castle = c, ep = ep ~= '-' and R.square(ep) or 0,
                half = tonumber(half) or 0, full = tonumber(full) or 1, king = {} }
  rescore(pos)
  return pos
end

function R.to_fen(pos)
  local rows = {}
  for r = 7, 0, -1 do
    local row, empty = {}, 0
    for f = 0, 7 do
      local p = pos.b[21 + r * 10 + f]
      if p == 0 then empty = empty + 1
      else
        if empty > 0 then row[#row + 1] = tostring(empty); empty = 0 end
        local ch = CHARS:sub(p > 0 and p or -p, p > 0 and p or -p)
        row[#row + 1] = p > 0 and ch:upper() or ch
      end
    end
    if empty > 0 then row[#row + 1] = tostring(empty) end
    rows[#rows + 1] = table.concat(row)
  end
  local c = pos.castle
  local cs = ((c & 1 ~= 0) and 'K' or '') .. ((c & 2 ~= 0) and 'Q' or '') .. ((c & 4 ~= 0) and 'k' or '') .. ((c & 8 ~= 0) and 'q' or '')
  return table.concat(rows, '/') .. ' ' .. (pos.side > 0 and 'w' or 'b') .. ' ' .. (cs ~= '' and cs or '-') .. ' ' ..
    (pos.ep ~= 0 and R.name(pos.ep) or '-') .. ' ' .. pos.half .. ' ' .. pos.full
end

-- what makes positions the same for the repetition rule: pieces, side, castling, en passant
function R.key(pos) return (R.to_fen(pos):match('^(%S+ %S+ %S+ %S+)')) end

------------------------------------------------------------------ attacks and moves

-- is square s attacked by side `by` (1 White, -1 Black)?
local function attacked(pos, s, by)
  local b = pos.b
  -- pawns: a white pawn attacks up the board (from s - 9 and s - 11)
  if by > 0 then
    if b[s - 9] == 1 or b[s - 11] == 1 then return true end
  else
    if b[s + 9] == -1 or b[s + 11] == -1 then return true end
  end
  local kn, ki, bi, ro, qu = 2 * by, 6 * by, 3 * by, 4 * by, 5 * by
  for i = 1, 8 do
    if b[s + N_DIRS[i]] == kn then return true end
    if b[s + K_DIRS[i]] == ki then return true end
  end
  for i = 1, 4 do
    local d = B_DIRS[i]
    local t = s + d
    local p = b[t]
    while p == 0 do t = t + d; p = b[t] end
    if p == bi or p == qu then return true end
    d = R_DIRS[i]
    t = s + d
    p = b[t]
    while p == 0 do t = t + d; p = b[t] end
    if p == ro or p == qu then return true end
  end
  return false
end
R.attacked = attacked

-- can move m leave its own king (on square king) in check? Only a king move, en passant, a move
-- made while in check, or a move of a piece on a line (rank, file or diagonal) with its king can:
-- for every other move the test after making it is skipped, which is most of the work saved
local function needs_check(m, king, in_check)
  if in_check then return true end
  local from = m % 128
  if from == king or m // 131072 == 1 then return true end
  local df = (from - 21) % 10 - (king - 21) % 10
  local dr = (from - 21) // 10 - (king - 21) // 10
  return df == 0 or dr == 0 or df == dr or df == -dr
end
R.needs_check = needs_check

function R.in_check(pos, side)
  side = side or pos.side
  return attacked(pos, pos.king[side], -side)
end

-- pseudo-legal moves (the king may be left in check) into list from n + 1; captures_only for the
-- quiescence search (promotions count as captures). Returns the new count.
local function gen(pos, list, n, captures_only)
  local b, side = pos.b, pos.side
  local fwd, start_rank, last_rank = side > 0 and 10 or -10, side > 0 and 1 or 6, side > 0 and 7 or 0
  local pl = pos.pl[side]
  for i = 1, pos.pn[side] do
    local s = pl[i]
    local p = b[s] * side
    do
      if p == 1 then
        local t = s + fwd
        local promo = (t - 21) // 10 == last_rank
        if b[t] == 0 then
          if promo then
            for q = 5, 2, -1 do n = n + 1; list[n] = s + t * 128 + q * 16384 end
          elseif not captures_only then
            n = n + 1; list[n] = s + t * 128
            if (s - 21) // 10 == start_rank and b[t + fwd] == 0 then n = n + 1; list[n] = s + (t + fwd) * 128 + 4 * 131072 end
          end
        end
        -- the two captures (no table for the directions: this runs for every pawn of every position)
        for k = 1, 2 do
          local c = k == 1 and t - 1 or t + 1
          local q = b[c]
          if q ~= OFF and q * side < 0 then
            if promo then
              for pr = 5, 2, -1 do n = n + 1; list[n] = s + c * 128 + pr * 16384 end
            else n = n + 1; list[n] = s + c * 128 end
          elseif c == pos.ep and q == 0 then
            n = n + 1; list[n] = s + c * 128 + 131072
          end
        end
      elseif p == 2 or p == 6 then
        local dirs = p == 2 and N_DIRS or K_DIRS
        for i = 1, 8 do
          local t = s + dirs[i]
          local q = b[t]
          if q ~= OFF and (q == 0 and not captures_only or q * side < 0) then n = n + 1; list[n] = s + t * 128 end
        end
        if p == 6 and not captures_only then
          -- castling: the rights, the squares between empty, the king not in, through or into check
          local k_bit, q_bit = side > 0 and 1 or 4, side > 0 and 2 or 8
          if pos.castle & k_bit ~= 0 and b[s + 1] == 0 and b[s + 2] == 0 and b[s + 3] == 4 * side and
              not attacked(pos, s, -side) and not attacked(pos, s + 1, -side) and not attacked(pos, s + 2, -side) then
            n = n + 1; list[n] = mv(s, s + 2, 0, 2)
          end
          if pos.castle & q_bit ~= 0 and b[s - 1] == 0 and b[s - 2] == 0 and b[s - 3] == 0 and b[s - 4] == 4 * side and
              not attacked(pos, s, -side) and not attacked(pos, s - 1, -side) and not attacked(pos, s - 2, -side) then
            n = n + 1; list[n] = mv(s, s - 2, 0, 2)
          end
        end
      else
        local dirs = p == 3 and B_DIRS or p == 4 and R_DIRS or K_DIRS
        for i = 1, #dirs do
          local d = dirs[i]
          local t = s + d
          local q = b[t]
          while q == 0 do
            if not captures_only then n = n + 1; list[n] = s + t * 128 end
            t = t + d; q = b[t]
          end
          if q ~= OFF and q * side < 0 then n = n + 1; list[n] = s + t * 128 end
        end
      end
    end
  end
  return n
end
R.gen = gen

-- castling rights lost when a piece leaves or reaches a square
local KEEP = {}
for s = 0, 119 do KEEP[s] = 15 end
KEEP[25], KEEP[28], KEEP[21] = 15 - 3, 15 - 1, 15 - 2       -- e1, h1, a1
KEEP[95], KEEP[98], KEEP[91] = 15 - 12, 15 - 4, 15 - 8      -- e8, h8, a8

-- the piece lists: a piece taken leaves its side's list (the last one takes its place), and comes
-- back at the end on unmake; a piece moving keeps its place
local function list_remove(pos, side, s)
  local pl, pi = pos.pl[side], pos.pi
  local n = pos.pn[side]
  local i = pi[s]
  local last = pl[n]
  pl[i], pi[last] = last, i
  pl[n], pi[s] = nil, nil
  pos.pn[side] = n - 1
end
local function list_add(pos, side, s)
  local n = pos.pn[side] + 1
  pos.pl[side][n], pos.pi[s], pos.pn[side] = s, n, n
end
local function list_move(pos, side, from, to)
  local i = pos.pi[from]
  pos.pl[side][i], pos.pi[to], pos.pi[from] = to, i, nil
end

function R.make(pos, m)
  local b = pos.b
  local from, to = m % 128, (m // 128) % 128
  local promo, flag = (m // 16384) % 8, m // 131072
  local p, side = b[from], pos.side
  local captured = b[to]
  local st, sp = pos.st, pos.sp
  st[sp + 1], st[sp + 2], st[sp + 3], st[sp + 4], st[sp + 5], st[sp + 6] = captured, pos.castle, pos.ep, pos.half, pos.score, pos.npm
  pos.sp = sp + 6
  local score = pos.score - worth(p, from)
  if captured ~= 0 then
    score = score - worth(captured, to)
    local a = captured > 0 and captured or -captured
    if a ~= 1 then pos.npm = pos.npm - VALUE[a] end
    list_remove(pos, -side, to)
  end
  b[from] = 0
  if flag == 1 then                                    -- en passant: the pawn beside goes
    local c = to - 10 * side
    score = score - worth(b[c], c)
    b[c] = 0
    list_remove(pos, -side, c)
  elseif flag == 2 then                                -- castling: the rook too
    local rf, rt = to > from and from + 3 or from - 4, to > from and from + 1 or from - 1
    score = score - worth(b[rf], rf) + worth(b[rf], rt)
    b[rt], b[rf] = b[rf], 0
    list_move(pos, side, rf, rt)
  end
  local pi = pos.pi
  local i = pi[from]
  pos.pl[side][i], pi[to], pi[from] = to, i, nil
  if promo ~= 0 then
    p = promo * side
    pos.npm = pos.npm + VALUE[promo]
  end
  b[to] = p
  score = score + worth(p, to)
  if p == 6 or p == -6 then pos.king[side] = to end
  pos.castle = pos.castle & KEEP[from] & KEEP[to]
  pos.ep = flag == 4 and (from + to) // 2 or 0
  pos.half = (p == 1 or p == -1 or captured ~= 0) and 0 or pos.half + 1
  if side < 0 then pos.full = pos.full + 1 end
  pos.side = -side
  pos.score = score
end

function R.unmake(pos, m)
  local b = pos.b
  local from, to = m % 128, (m // 128) % 128
  local promo, flag = (m // 16384) % 8, m // 131072
  local side = -pos.side
  pos.side = side
  local st, sp = pos.st, pos.sp - 6
  pos.sp = sp
  local captured = st[sp + 1]
  local p = b[to]
  if promo ~= 0 then p = side end
  b[from], b[to] = p, captured
  local pi = pos.pi
  local i = pi[to]
  pos.pl[side][i], pi[from], pi[to] = from, i, nil
  if captured ~= 0 then list_add(pos, -side, to) end
  if p == 6 or p == -6 then pos.king[side] = from end
  if flag == 1 then
    local c = to - 10 * side
    b[c] = -side
    list_add(pos, -side, c)
  elseif flag == 2 then
    local rf, rt = to > from and from + 3 or from - 4, to > from and from + 1 or from - 1
    b[rf], b[rt] = b[rt], 0
    list_move(pos, side, rt, rf)
  end
  if side < 0 then pos.full = pos.full - 1 end
  pos.castle, pos.ep, pos.half, pos.score, pos.npm = st[sp + 2], st[sp + 3], st[sp + 4], st[sp + 5], st[sp + 6]
end

-- the legal moves of the side to move
function R.legal(pos)
  local list = {}
  local n = gen(pos, list, 0, false)
  local out = {}
  local side = pos.side
  local king = pos.king[side]
  local chk = attacked(pos, king, -side)
  for i = 1, n do
    local m = list[i]
    local u = R.make(pos, m)
    if not needs_check(m, king, chk) or not attacked(pos, pos.king[side], -side) then out[#out + 1] = m end
    R.unmake(pos, m, u)
  end
  return out
end

------------------------------------------------------------------ notation

function R.uci(m)
  local promo = (m // 16384) % 8
  return R.name(m % 128) .. R.name((m // 128) % 128) .. (promo ~= 0 and CHARS:sub(promo, promo) or '')
end

-- the legal move a UCI string names, or nil
function R.from_uci(pos, s)
  if type(s) ~= 'string' or #s < 4 then return nil end
  for _, m in ipairs(R.legal(pos)) do
    if R.uci(m) == s or (R.move_promo(m) == 0 and R.uci(m) == s:sub(1, 4) and #s == 4) then return m end
  end
  return nil
end

-- SAN, with + or # (needs the position before the move)
function R.san(pos, m)
  local b = pos.b
  local from, to, promo, flag = m % 128, (m // 128) % 128, (m // 16384) % 8, m // 131072
  local p = b[from]
  local a = p > 0 and p or -p
  local s
  if flag == 2 then
    s = to > from and 'O-O' or 'O-O-O'
  elseif a == 1 then
    s = (b[to] ~= 0 or flag == 1) and (R.name(from):sub(1, 1) .. 'x' .. R.name(to)) or R.name(to)
    if promo ~= 0 then s = s .. '=' .. CHARS:sub(promo, promo):upper() end
  else
    -- another piece of the same kind that can go to the same square: name the file, the rank or both
    local same_file, same_rank, other = false, false, false
    for _, o in ipairs(R.legal(pos)) do
      local of = o % 128
      if of ~= from and (o // 128) % 128 == to and b[of] == p then
        other = true
        if R.file(of) == R.file(from) then same_file = true end
        if R.rank(of) == R.rank(from) then same_rank = true end
      end
    end
    local dis = ''
    if other then
      local n = R.name(from)
      if not same_file then dis = n:sub(1, 1)
      elseif not same_rank then dis = n:sub(2, 2)
      else dis = n end
    end
    s = CHARS:sub(a, a):upper() .. dis .. (b[to] ~= 0 and 'x' or '') .. R.name(to)
  end
  local u = R.make(pos, m)
  if R.in_check(pos) then s = s .. (#R.legal(pos) == 0 and '#' or '+') end
  R.unmake(pos, m, u)
  return s
end

------------------------------------------------------------------ the end of a game

-- too little to mate: kings alone, or one minor piece, or bishops all on one colour
function R.insufficient(pos)
  local minors, bishops_colour = 0, {}
  for s = 21, 98 do
    local p = pos.b[s]
    if p ~= 0 and p ~= OFF then
      local a = p > 0 and p or -p
      if a == 1 or a == 4 or a == 5 then return false end
      if a == 2 then minors = minors + 1 end
      if a == 3 then minors = minors + 1; bishops_colour[(R.file(s) + R.rank(s)) % 2] = true end
    end
  end
  if minors <= 1 then return true end
  -- only bishops, all on squares of one colour
  local knights = false
  for s = 21, 98 do local p = pos.b[s]; if p == 2 or p == -2 then knights = true end end
  return not knights and not (bishops_colour[0] and bishops_colour[1])
end

-- nil while the game goes on, else (result, why): result 1 White wins, -1 Black wins, 0 a draw.
-- keys: the R.key of every position so far (for the repetition rule), the current one last.
function R.outcome(pos, keys)
  if #R.legal(pos) == 0 then
    if R.in_check(pos) then return -pos.side, 'checkmate' end
    return 0, 'stalemate'
  end
  if pos.half >= 100 then return 0, 'the 50-move rule' end
  if R.insufficient(pos) then return 0, 'too little material' end
  if keys and #keys > 0 then
    local now, seen = keys[#keys], 0
    for i = 1, #keys do if keys[i] == now then seen = seen + 1 end end
    if seen >= 3 then return 0, 'threefold repetition' end
  end
  return nil
end

-- perft: the number of positions after `depth` plies (the standard check of a move generator)
function R.perft(pos, depth)
  if depth == 0 then return 1 end
  local list = {}
  local n = gen(pos, list, 0, false)
  local total, side = 0, pos.side
  local king = pos.king[side]
  local chk = attacked(pos, king, -side)
  for i = 1, n do
    local m = list[i]
    local u = R.make(pos, m)
    if not needs_check(m, king, chk) or not attacked(pos, pos.king[side], -side) then total = total + R.perft(pos, depth - 1) end
    R.unmake(pos, m, u)
  end
  return total
end

return R
end

-- Chess for XTOS Licorice, API 2.9 (uses tools/gamekit): a whole game against the reader at four
-- levels, or two players on one reader. Tap a piece (its moves are marked), then a square; a pawn
-- reaching the last rank asks what it becomes. Undo takes back your last move (and the reply),
-- Hint frames a good move, New game picks the opponent and your side.
--
-- rules.lua holds the rules (legal moves, check, mate and the draws); engine.lua the reader's
-- player. It thinks in a coroutine resumed from ctx:after timers in slices of about 200 ms, on a
-- copy of the position, so callbacks stay under the host's limits and taps (Undo, New game) still
-- come through; nothing runs while it is your move. The game is kept as its moves in game.txt and
-- replayed on the next start.

local R = require('rules')
local E = require('engine')
local RUNS = require('pieces')

local W, H = kit.W, kit.H
local SQ = 56
local BX, BY = (W - 8 * SQ) // 2, 150
local BTN_Y, BTN_H = 704, 60
local SLICE_MS = 200

local pos = R.from_fen(R.START)
local history = {}              -- { m, u, san } per move played
local keys = {}                 -- R.key of every position so far (the repetition rule)
local mode, level, me = 'ai', 2, 1   -- 'ai' or 'two'; E.LEVELS index; your side (1 White, -1 Black)
local sel, targets = nil, {}    -- the square picked and its legal moves
local hint, last = nil, nil     -- { from, to } squares
local result = nil              -- { r, why } once the game is over
local think = nil               -- { co, kind = 'move' or 'hint' } while the reader thinks
local msg, ERR = nil, nil

local LETTER = { 'p', 'n', 'b', 'r', 'q', 'k' }

------------------------------------------------------------------ the game

local function save()
  local t = {}
  for i, h in ipairs(history) do t[i] = R.uci(h.m) end
  kit.write('game.txt', 'mode=' .. mode .. '\nlevel=' .. level .. '\nme=' .. me .. '\nmoves=' .. table.concat(t, ' '))
end

local function side_name(s) return s > 0 and 'White' or 'Black' end

local function check_end()
  local r, why = R.outcome(pos, keys)
  result = r and { r = r, why = why } or nil
  if not result then return end
  if r == 0 then msg = 'Draw: ' .. why .. '.'
  elseif mode == 'ai' then msg = (r == me and 'Checkmate. You win!' or 'Checkmate. The reader wins.')
  else msg = 'Checkmate. ' .. side_name(r) .. ' wins.' end
end

local function play(m)
  local san = R.san(pos, m)
  local u = R.make(pos, m)
  history[#history + 1] = { m = m, u = u, san = san }
  keys[#keys + 1] = R.key(pos)
  last = { R.move_from(m), R.move_to(m) }
  sel, targets, hint = nil, {}, nil
  msg = nil
  check_end()
  kit.moved()
end

local start_thinking

-- the reader's turn: start thinking once the frame with your move is up
local function after_move()
  save()
  if mode == 'ai' and not result and pos.side ~= me then start_thinking('move') end
end

local function new_game(m, lv, side)
  think = nil
  mode, level, me = m, lv or level, side or 1
  pos = R.from_fen(R.START)
  history, keys = {}, { R.key(pos) }
  sel, targets, hint, last, result, msg = nil, {}, nil, nil, nil, nil
  if mode == 'ai' then
    msg = 'You play ' .. side_name(me) .. ' against the reader (' .. E.LEVELS[level].name .. ').'
  else
    msg = 'Two players: White starts.'
  end
  after_move()
end

local function undo()
  think = nil
  if #history == 0 then return end
  -- against the reader: back to your move (your move and its reply); two players: one move
  repeat
    local h = table.remove(history)
    R.unmake(pos, h.m, h.u)
    table.remove(keys)
  until #history == 0 or mode ~= 'ai' or pos.side == me
  local h = history[#history]
  last = h and { R.move_from(h.m), R.move_to(h.m) } or nil
  sel, targets, hint, result = nil, {}, nil, nil
  msg = 'Move taken back.'
  check_end()
  save()
  if mode == 'ai' and pos.side ~= me then start_thinking('move') end
end

local function load()
  local t = kit.kv(kit.read('game.txt'))
  local m = t.mode == 'two' and 'two' or 'ai'
  local lv = tonumber(t.level)
  if not E.LEVELS[lv or 0] then lv = 2 end
  local side = tonumber(t.me) == -1 and -1 or 1
  if not t.mode then new_game('ai', 2, 1); return end
  think = nil
  mode, level, me = m, lv, side
  pos = R.from_fen(R.START)
  history, keys = {}, { R.key(pos) }
  for s in (t.moves or ''):gmatch('%S+') do
    local mv = R.from_uci(pos, s)
    if not mv then break end
    play(mv)
  end
  sel, targets, hint = nil, {}, nil
  check_end()
  if not result then msg = nil end
  if mode == 'ai' and not result and pos.side ~= me then start_thinking('move') end
end

------------------------------------------------------------------ the reader thinking

local function step(c)
  local th = think
  if not th then return end
  local ok, best = coroutine.resume(th.co)
  if think ~= th then return end                     -- Undo or New game while it thought
  if not ok then think = nil; ERR = tostring(best); kit.refresh(); return end
  if coroutine.status(th.co) ~= 'dead' then
    pcall(function() ctx:after(1, step) end)
    return
  end
  think = nil
  if not best then kit.refresh(); return end
  -- best is a move of the copy: the same number in the real position
  if th.kind == 'move' then
    play(best)
    save()
  else
    hint = { R.move_from(best), R.move_to(best) }
    msg = 'Hint: ' .. R.san(pos, best) .. '.'
  end
  kit.refresh()
end

start_thinking = function(kind)
  local copy = R.from_fen(R.to_fen(pos))
  local lv = kind == 'hint' and 3 or level
  local limit = kind == 'hint' and 2000 or nil
  local co = coroutine.create(function()
    return E.think(copy, lv, { clock = function() return kit.now_ms() or 0 end, slice_ms = SLICE_MS, limit_ms = limit })
  end)
  think = { co = co, kind = kind }
  pcall(function() ctx:after(30, step) end)
end

------------------------------------------------------------------ drawing

local function square_xy(s)
  local f, r = R.file(s), R.rank(s)
  local flip = (mode == 'ai' and me < 0)
  if flip then f, r = 7 - f, 7 - r end
  return BX + f * SQ, BY + (7 - r) * SQ
end

local function draw_piece(gg, p, x, y)
  local key = LETTER[p > 0 and p or -p]
  if p > 0 then key = key:upper() end
  for _k, run in ipairs(RUNS[key] or {}) do
    gg:rect(x + (run[2] - 1) * 2, y + (run[1] - 1) * 2, (run[3] - run[2] + 1) * 2, run[4] * 2, { fill = true })
  end
end

local function corners(gg, s)
  local x, y = square_xy(s)
  local L, E2 = 14, SQ - 4
  for _j, c in ipairs({ { 0, 0, 0, 0 }, { SQ - L, 0, E2, 0 }, { 0, E2, 0, SQ - L }, { SQ - L, E2, E2, SQ - L } }) do
    gg:rect(x + c[1], y + c[2], L, 4, { fill = true })
    gg:rect(x + c[3], y + c[4], 4, L, { fill = true })
  end
end

local function draw_board(gg)
  for r = 0, 7 do
    for f = 0, 7 do
      local s = 21 + r * 10 + f
      local x, y = square_xy(s)
      if (f + r) % 2 == 0 then gg:rect(x + 3, y + 3, SQ - 6, SQ - 6, { line_width = 1 }) end      -- a dark square
      local p = pos.b[s]
      if p ~= 0 then draw_piece(gg, p, x + 8, y + 8) end
    end
  end
  gg:rect(BX - 2, BY - 2, 8 * SQ + 4, 8 * SQ + 4, { line_width = 2 })
  local small = kit.font('small')
  local flip = (mode == 'ai' and me < 0)
  for k = 1, 8 do
    local file = flip and 9 - k or k
    local rank = flip and k or 9 - k
    gg:text(BX + (k - 1) * SQ + SQ // 2 - 4, BY + 8 * SQ + 4, ('abcdefgh'):sub(file, file), { font = small })
    gg:text(2, BY + (k - 1) * SQ + SQ // 2 - 10, tostring(rank), { font = small })
  end
  if last then for _k, s in ipairs(last) do corners(gg, s) end end
  -- a king in check: a double frame
  if not result or result.why == 'checkmate' then
    if R.in_check(pos) then
      local x, y = square_xy(pos.king[pos.side])
      gg:rect(x + 1, y + 1, SQ - 2, SQ - 2, { line_width = 3 }); gg:rect(x + 7, y + 7, SQ - 14, SQ - 14, { line_width = 2 })
    end
  end
  if sel then
    local x, y = square_xy(sel)
    gg:rect(x + 1, y + 1, SQ - 2, SQ - 2, { line_width = 4 })
    -- where it can go: a dot on an empty square, a ring round a piece it takes
    local seen = {}
    for _k, m in ipairs(targets) do
      local t = R.move_to(m)
      if not seen[t] then
        seen[t] = true
        local tx, ty = square_xy(t)
        if pos.b[t] ~= 0 then gg:circle(tx + SQ // 2, ty + SQ // 2, SQ // 2 - 3, { line_width = 3 })
        else gg:circle(tx + SQ // 2, ty + SQ // 2, 7, { fill = true }) end
      end
    end
  end
  if hint then
    for _k, s in ipairs(hint) do
      local x, y = square_xy(s)
      gg:rect(x + 1, y + 1, SQ - 2, SQ - 2, { line_width = 2 }); gg:rect(x + 6, y + 6, SQ - 12, SQ - 12, { line_width = 2 })
    end
  end
end

-- the last moves, numbered: "11. Nf3 Nc6  12. Bb5"
local function recent()
  local out = {}
  local first = math.max(1, #history - 3)
  -- start on a White move when there is one before
  for i = first, #history do
    local n = (i + 1) // 2
    if i % 2 == 1 then out[#out + 1] = n .. '. ' .. history[i].san
    elseif i == first then out[#out + 1] = n .. '... ' .. history[i].san
    else out[#out] = out[#out] .. ' ' .. history[i].san end
  end
  return table.concat(out, '   ')
end

local BUTTONS = { 'Undo', 'Hint', 'New game' }
local function button_rect(k)
  local bw = math.floor((W - 24 - 2 * 8) / 3)
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

local function status()
  if result then return result.r == 0 and 'Draw' or 'Checkmate' end
  local check = R.in_check(pos) and ' (check)' or ''
  if mode == 'ai' then
    if think and think.kind == 'move' then return 'The reader is thinking…' end
    if pos.side == me then return 'Your move' .. check end
    return side_name(pos.side) .. ' to move' .. check
  end
  return side_name(pos.side) .. ' to move' .. check
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    gg:text(12, 12, 'Chess', { font = kit.font('large') })
    local who = mode == 'ai' and ('You: ' .. side_name(me) .. '   reader: ' .. E.LEVELS[level].name) or 'Two players'
    gg:text(12, 52, kit.short(who .. '   move ' .. pos.full, 48), { font = kit.font('small') })
    gg:line(0, 90, W, 90)
    if kit.modal() then kit.draw_modal(gg); return end
    gg:text(12, 106, status(), { font = kit.font('medium') })
    draw_board(gg)
    local lines = {}
    if #history > 0 then lines[#lines + 1] = recent() end
    if msg then for _k, l in ipairs(kit.wrap(msg, 'small', W - 24)) do lines[#lines + 1] = l end end
    for k, l in ipairs(lines) do
      if k > 3 then break end
      gg:text(12, BY + 8 * SQ + 30 + (k - 1) * 22, kit.short(l, 52), { font = kit.font('small') })
    end
    for k, b in ipairs(BUTTONS) do
      local x, y, bw, bh = button_rect(k)
      kit.button(gg, x, y, bw, bh, b)
    end
    if ERR then gg:text(12, H - 30, kit.short('ERR ' .. ERR, 48), { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function square_at(x, y)
  if x < BX or x >= BX + 8 * SQ or y < BY or y >= BY + 8 * SQ then return nil end
  local f, r = (x - BX) // SQ, 7 - (y - BY) // SQ
  if mode == 'ai' and me < 0 then f, r = 7 - f, 7 - r end
  return 21 + r * 10 + f
end

local function choose_side(lv)
  kit.show({ title = 'Play as', lines = { 'Against the reader, ' .. E.LEVELS[lv].name .. '.' },
             rows = { { { 'White', function() kit.close(); new_game('ai', lv, 1) end },
                        { 'Black', function() kit.close(); new_game('ai', lv, -1) end } },
                      { { 'Either', function() kit.close(); new_game('ai', lv, math.random(2) == 1 and 1 or -1) end } },
                      { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function new_game_menu()
  local function lv(i) return { E.LEVELS[i].name, function() kit.close(); choose_side(i) end } end
  kit.show({ title = 'New game', lines = { 'Play against the reader, or two players on one reader.' },
             rows = { { lv(1), lv(2) }, { lv(3), lv(4) },
                      { { 'Two players', function() kit.close(); new_game('two', level, 1) end } },
                      { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

-- a pawn on the last rank: what it becomes
local function choose_promotion(list)
  local function pick(promo, label)
    return { label, function()
      kit.close()
      for _k, m in ipairs(list) do
        if R.move_promo(m) == promo then play(m); after_move(); return end
      end
    end }
  end
  kit.show({ title = 'Promote to', rows = { { pick(5, 'Queen'), pick(4, 'Rook') }, { pick(3, 'Bishop'), pick(2, 'Knight') },
                                            { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function my_turn()
  if result or think then return false end
  return mode == 'two' or pos.side == me
end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  for k = 1, 3 do
    local bx, by, bw, bh = button_rect(k)
    if x >= bx and x < bx + bw and y >= by and y < by + bh then
      if k == 1 then undo()
      elseif k == 2 then
        if my_turn() then msg = 'Looking for a good move…'; hint = nil; start_thinking('hint') end
      else new_game_menu() end
      return
    end
  end
  if not my_turn() then return end
  local s = square_at(x, y)
  if not s then sel, targets = nil, {}; return end
  local p = pos.b[s]
  if p ~= 0 and (p > 0) == (pos.side > 0) then
    if sel == s then sel, targets = nil, {}
    else
      sel, targets = s, {}
      for _k, m in ipairs(R.legal(pos)) do if R.move_from(m) == s then targets[#targets + 1] = m end end
      msg = #targets == 0 and 'That piece cannot move.' or nil
    end
  elseif sel then
    local list = {}
    for _k, m in ipairs(targets) do if R.move_to(m) == s then list[#list + 1] = m end end
    if #list == 0 then sel, targets = nil, {}; return end
    if #list > 1 then choose_promotion(list); return end
    play(list[1])
    after_move()
  end
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if kit.modal() and ev.key == 'back' and kit.modal().cancel then kit.modal().cancel() end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  local ok, e = pcall(load)
  if not ok then ERR = tostring(e) end
end
function on_leave() think = nil; pcall(save) end

if rawget(_G, '__TEST') then
  __TEST.api = { pos = function() return pos end, R = R, E = E, square_xy = square_xy, history = function() return history end,
                 result = function() return result end, thinking = function() return think end, step = step,
                 mode = function() return mode end, me = function() return me end, level = function() return level end,
                 new_game = new_game, sel = function() return sel end, hint = function() return hint end,
                 set_position = function(fen)
                   think = nil
                   pos = R.from_fen(fen); history, keys = {}, { R.key(pos) }
                   sel, targets, hint, last, result, msg = nil, {}, nil, nil, nil, nil
                 end }
end
